var result=new System.Collections.Generic.List<object>();foreach(var folder in new[]{"ApartmentDoor_RedTufted_01","ApartmentDoor_WoodSlats_01","ApartmentDoor_DarkUpholstery_01"}){string f="Assets/Maps/Buildings/Textures/"+folder;var m=UnityEditor.AssetDatabase.LoadAssetAtPath<Material>(f+"/M_"+folder+"_URP.mat");foreach(var slot in new[]{"_BaseMap","_BumpMap","_ParallaxMap","_OcclusionMap","_MetallicGlossMap"})if(!m.GetTexture(slot))throw new Exception(folder+slot);var normal=(UnityEditor.TextureImporter)UnityEditor.AssetImporter.GetAtPath(UnityEditor.AssetDatabase.GetAssetPath(m.GetTexture("_BumpMap")));result.Add(new{folder=folder,baseSize=m.GetTexture("_BaseMap").width+"x"+m.GetTexture("_BaseMap").height,normalType=normal.textureType.ToString(),wrap=normal.wrapMode.ToString(),shaderErrors=UnityEditor.ShaderUtil.ShaderHasError(m.shader),maps=System.IO.Directory.GetFiles(f,"*.png").Length});}return result;
